def components(grid):
    from collections import Counter
    bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
    R,C=len(grid),max(map(len,grid)); seen=set(); comps=[]
    at=lambda r,c: grid[r][c] if c<len(grid[r]) else bg
    for r in range(R):
        for c in range(C):
            if at(r,c)==bg or (r,c) in seen: continue
            color=at(r,c); stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                a,b=stack.pop(); cells.append((a,b))
                for da,db in [(1,0),(-1,0),(0,1),(0,-1)]:
                    x,y=a+da,b+db
                    if 0<=x<R and 0<=y<C and (x,y) not in seen and at(x,y)==color:
                        seen.add((x,y)); stack.append((x,y))
            comps.append((color,cells))
    return bg,comps
